function ringPicoLines(id,script) {
 let cast=[];
 return script.lines.map(([who,text],index)=>{
  if(who&&!cast.includes(who))cast=[...cast,who];
  const expression=!who?null:/파르페.*먹|퍼먹|포크.*빨/.test(text)&&who==='라나'?'parfait':
   /생글생글|싱글벙글|생긋|미소|윙크/.test(text)?'smile':
   /히익|질겁|놀라|꺄아|으아|네엣|어\?!|으응/.test(text)?'shock':
   /부들부들|인상 팍|정색|당장|꺼져|닥치|죽인다/.test(text)?'angry':
   /피곤|풀수면|3시간|하아/.test(text)?'tired':'neutral';
  const thought=who==='타키'&&text.startsWith('(')&&/죽인다|신고할까|물론 수업|속으로/.test(text);
  // Deliberately restrained: entrances ring once; no giant onomatopoeia overlays.
  const door=id==='intro'&&who==='아논'&&index===2||id==='intro'&&who==='토모리'&&index===8;
  const beat={...(id==='intro'?{cast:[...cast]}:{}),...(thought?{thought:true}:{}),...(door?{fx:'door',caption:'짤랑~',enter:who}:{})};
  return [who,text,expression,beat];
 });
}
function applyComicStories(stories) {
 for(const [id,story] of Object.entries(stories)) {
  const rewrite=ringPicoScripts[id];if(!rewrite)continue;
  const source=ringPicoCompatibility[id]||rewrite;
  story.title=rewrite.title;story.lines=ringPicoLines(id,source);story.comicRevision=2;
  if(rewrite.choice){
   if(!story.choice||story.choice.options.length!==rewrite.choice.options.length)throw Error('Choice mismatch: '+id);
   story.choice.prompt=rewrite.choice.prompt;
   rewrite.choice.options.forEach((option,i)=>{story.choice.options[i].label=option.label;story.choice.options[i].reply=option.reply.slice();});
  }
 }
}

